from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Literal

# Doc types whose GT was generated by Tesseract at download time (silver standard).
# For these, text-comparison metrics (CER/WER/NED/word-F1) are meaningless;
# the LLM judge — which scores against the original image — is the only valid metric.
# "legal" was here until all six of its documents were re-transcribed and
# consensus-verified (see documents/gt_provenance.json).
SILVER_GT_DOC_TYPES: frozenset[str] = frozenset({"report", "newspaper"})

# Individual doc stems whose GT cannot support text metrics.
#
# scanned_001-004 used to live here: their GT covered the whole multi-page
# document while the benchmark image is page 1 only, so recall was capped
# far below 1.0 (a perfect read of scanned_004 scored ~0.38). That was an
# annotation defect, not a property of the documents — the source dataset
# carries per-page text that the corpus builder never used. Rebuilt from
# page 1 by scripts/fix_scanned_legacy_gt.py, they now have GT that matches
# the image and are scored normally.
SILVER_GT_DOCS: frozenset[str] = frozenset()

# Source datasets whose plain-text ground truth IS markdown — the annotation was
# authored as markdown, so `_gt.txt` doubles as the markdown reference and no
# separate `_markdown_gt.md` sidecar exists.
MARKDOWN_NATIVE_DATASETS: frozenset[str] = frozenset({"getomni-ai/ocr-benchmark"})

DOCUMENTS_ROOT = Path(__file__).parent.parent / "documents"


@dataclass
class GroundTruth:
    document_path: str
    tier: Literal["easy", "medium", "hard"]
    doc_type: str
    plain_text: str
    table_html: str | None = None   # populated for financial table docs
    has_formulas: bool = False      # flag for scientific docs
    # "human"           — the source dataset's own human annotation
    # "model_verified"   — transcribed by a vision model and cross-checked
    #                      against OCR engine consensus (documents/gt_provenance.json).
    #                      Trustworthy for text metrics, but reported separately
    #                      so a reader can weigh it differently to human GT.
    # "silver_tesseract" — machine-generated at corpus-build time, unreliable;
    #                      excluded from text metrics, judge only.
    gt_source: Literal["human", "model_verified", "silver_tesseract"] = "human"

    # --- Per-leg references -------------------------------------------------
    # Leg 2. Either a `_markdown_gt.md` sidecar or, for the markdown-native
    # datasets, the plain-text GT itself.
    markdown: str | None = None
    markdown_source: str | None = None   # "sidecar" | "gt_txt_is_markdown"
    # Leg 3 provenance, recorded per file by the corpus builder. Five of the 45
    # references were derived from schema field names rather than printed page
    # columns — see documents/gt_limitations.json, id "weak-table-references".
    table_html_source: str | None = None
    # Legs 4 and 5.
    json_schema: dict[str, Any] | None = None
    true_json: Any | None = None
    field_provenance: dict[str, Any] | None = None
    structured_note: str | None = None
    # Leg 6: word boxes from the sidecar, where one exists. granularity is the
    # sidecar's stated unit — "line" (SROIE) makes the scorer lift predicted
    # words to lines before matching.
    word_boxes: list[dict[str, Any]] | None = None
    word_boxes_granularity: str | None = None

    dataset: str | None = None
    metadata: dict[str, Any] = field(default_factory=dict)

    @property
    def inference_schema(self) -> dict[str, Any] | None:
        """The answer-free request contract, separate from scoring coverage."""
        if self.json_schema is None:
            return None
        from evaluation.schema_contract import sampled_request_schema
        return sampled_request_schema(self)

    # Legs whose reference exists for this document. The scorers ask this
    # rather than probing file paths — see the loader docstring.
    def has_gt_for(self, leg: str) -> bool:
        if leg == "text":
            return bool(self.plain_text) and self.gt_source != "silver_tesseract"
        if leg == "markdown":
            return bool(self.markdown or self.metadata.get('reviewed_markdown_catalogue'))
        if leg == "tables":
            # A table page is one a HUMAN marked as such (table_html sidecar);
            # the image checklist is the reference the verdicts are scored
            # against, not the eligibility rule. Letting the checklist decide
            # (2026-10-01, briefly) added 17 fax forms, letters and memos where
            # Gemini had catalogued a grid and every engine scored 0.
            return bool(self.table_html) and self.doc_type != "chart"
        if leg == "schema":
            return self.true_json is not None
        if leg == "key_value":
            return self.true_json is not None
        if leg == "geometry":
            return bool(self.word_boxes)
        raise ValueError(f"Unknown leg: {leg!r}")

    def scalar_field_count(self) -> int:
        """Reference fields outside arrays — the key-value leg's unit."""
        if self.true_json is None:
            return 0
        from evaluation.structured_metrics import walk_fields
        return sum(1 for f in walk_fields(self.true_json, self.json_schema)
                   if f.path and not f.in_array)

    def printed_pair_count(self) -> int | None:
        """Scalar reference fields the page prints as label:value pairs (stage
        1), or None when stage 1 has not run for this document."""
        from evaluation.kv_schema_code import load_aliases
        reviewed = self.metadata.get('structured_gold_reference')
        aliases = reviewed.get('kv_aliases') if reviewed is not None else load_aliases(Path(self.document_path).stem)
        if reviewed is not None:
            if aliases is None:
                return None
            excluded = set(reviewed.get('excluded_fields', []))
            return sum(1 for path, a in aliases.items()
                       if path not in excluded and a.get('is_printed_pair'))
        if not aliases:
            return None
        return sum(1 for path, a in aliases.items() if "[" not in path and a.get("is_printed_pair"))

    def missing_gt_reason(self, leg: str) -> str:
        """Why this document contributes nothing to `leg`. Reportable, not an error."""
        if leg == "text" and self.gt_source == "silver_tesseract":
            return "silver ground truth — text metrics excluded, judge only"
        if leg == "key_value" and self.true_json is not None:
            return "too few scalar fields for key-value evaluation (fewer than 3)"
        return {
            "text": "no plain-text sidecar",
            "markdown": "no markdown reference",
            "tables": "no table reference",
            "key_value": "no structured reference",
            "schema": "no structured reference",
            "geometry": "no word-box reference for this document (17 of 93 have one)",
        }.get(leg, f"no reference for leg {leg!r}")


def _load_provenance() -> dict[str, dict]:
    """Documents whose GT was produced by a model rather than the source dataset.

    Keyed by document stem. The file wraps them in a "documents" object beside
    an "_about" note; reading the wrapper instead meant no document ever
    classified as model_verified, so eight consensus-verified documents were
    reported as human-annotated and report_000 stayed misfiled as silver.
    """
    path = DOCUMENTS_ROOT / "gt_provenance.json"
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    documents = data.get("documents") if isinstance(data, dict) else None
    if isinstance(documents, dict):
        return documents
    # Older layout: stems at the top level, with "_" keys as metadata.
    return {k: v for k, v in (data or {}).items() if not k.startswith("_")}


MODEL_VERIFIED_GT: dict[str, dict] = _load_provenance()


def _load_manifest() -> dict[str, dict]:
    """Corpus manifest keyed by document stem — the source dataset per document.

    Needed by the markdown leg: for the markdown-native datasets there is no
    `_markdown_gt.md` sidecar because `_gt.txt` already is markdown, and
    guessing that from the text's shape would be a heuristic where a fact is
    available.
    """
    path = DOCUMENTS_ROOT / "manifest.json"
    if not path.exists():
        return {}
    try:
        entries = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return {Path(e["file"]).stem: e for e in entries if e.get("file")}


MANIFEST: dict[str, dict] = _load_manifest()


def _classify_gt(doc_path: Path, doc_type: str) -> str:
    """Model-verified GT wins over the silver classification it replaced."""
    if doc_path.stem in MODEL_VERIFIED_GT:
        return "model_verified"
    if doc_type in SILVER_GT_DOC_TYPES or doc_path.stem in SILVER_GT_DOCS:
        return "silver_tesseract"
    return "human"


class GroundTruthLoader:
    """The one way to read ground truth.

    Everything that needs to know what a document's reference says — scorers,
    the report, any verification — goes through `load()`. Reading a sidecar
    directly is how a repair once landed on disk without landing in the object
    the benchmark scores against, and the script that checked the repair read
    the file rather than the loader, so it confirmed a fix scoring never saw.
    """

    def load(self, document_path: Path) -> GroundTruth:
        """
        Finds the ground-truth sidecars next to document_path and returns a
        GroundTruth carrying every leg's reference. Tier and doc_type are
        inferred from the directory structure: documents/{tier}/{doc_type}/name.
        """
        tier, doc_type = self._infer_tier_type(document_path)
        gt_json = document_path.parent / (document_path.stem + "_gt.json")
        gt_txt = document_path.parent / (document_path.stem + "_gt.txt")

        if gt_json.exists():
            # Both sidecars can carry the document's text and only this one is
            # read. A repair applied to the other silently does nothing — that
            # happened to six invoices and went unnoticed because the audit
            # tooling read the file the repair had written. Fail loudly instead.
            if gt_txt.exists():
                import re as _re
                _norm = lambda s: _re.sub(r"\s+", " ", s or "").strip()  # noqa: E731
                _json_text = json.loads(gt_json.read_text(encoding="utf-8")).get("plain_text", "")
                if _norm(_json_text) != _norm(gt_txt.read_text(encoding="utf-8")):
                    raise ValueError(
                        f"Ground truth sidecars disagree for {document_path.name}: "
                        f"{gt_json.name} plain_text differs from {gt_txt.name}. "
                        f"{gt_json.name} is the file the benchmark reads. Sync them "
                        f"before running, or scores will be measured against stale text."
                    )
            gt = self._load_json_gt(document_path, gt_json, tier, doc_type)
        elif gt_txt.exists():
            gt = self._load_txt_gt(document_path, gt_txt, tier, doc_type)
        else:
            raise FileNotFoundError(
                f"No ground truth sidecar found for {document_path}. "
                f"Expected {gt_json} or {gt_txt}."
            )

        self._attach_markdown(document_path, gt)
        self._attach_structured(document_path, gt)
        self._attach_geometry(document_path, gt)
        self._apply_reviewed_reference_repairs(document_path, gt)
        if gt.word_boxes:
            # The datasets do not certify every printed mark on the page.
            # Use a fixed reference-derived region, never the engine's output,
            # for extra-box/text diagnostics. Keep the boundary inspectable.
            boxes = [w['bbox'] for w in gt.word_boxes]
            gt.metadata['geometry_scope'] = {
                'version': 'annotation-envelope-v1',
                'regions': [[min(b[0] for b in boxes), min(b[1] for b in boxes),
                             max(b[2] for b in boxes), max(b[3] for b in boxes)]],
                'excluded_regions': [r['bbox'] for r in
                    gt.metadata.get('geometry_reference_repairs', {}).get('excluded_boxes', [])
                    if 'unreadable' in r.get('reason', '')],
                'basis': 'bounding envelope of retained dataset annotations; unreadable reviewed regions excluded',
                'limitation': 'Annotations inside the envelope can still be incomplete. This is region-scoped precision, not certified full-page false-positive accuracy.',
            }
        from evaluation.structured_references import load_gold_structured
        structured_gold = load_gold_structured(document_path)
        if structured_gold is not None:
            gt.true_json = structured_gold['true_json']
            gt.json_schema = structured_gold['json_schema']
            gt.structured_note = 'Human-reviewed structured reference (schema and KV gold slot)'
            gt.metadata['structured_gold_reference'] = structured_gold
            from evaluation.structured_references import load_kv_label_review
            label_review = load_kv_label_review(document_path, structured_gold)
            if label_review:
                gt.metadata['kv_label_review'] = label_review
            previous_repairs = gt.metadata.get('structured_reference_repairs', {})
            gt.metadata['structured_reference_repairs'] = {
                'version': 'human-structured-gold-v1',
                'excluded_fields': structured_gold.get('excluded_fields', []),
                'previous_repairs': previous_repairs,
                'gold_path': structured_gold['path'],
            }
        # Only an explicit human save/accept creates this slot. Proposed
        # patches stay separate; without gold the original reference above wins.
        from evaluation.table_references import load_gold_table, load_original_table
        if gt.doc_type == "shipping":
            original = load_original_table(document_path)
            gt.metadata["table_original_reference"] = original or {"table_html": gt.table_html}
        gold = load_gold_table(document_path)
        if gold is not None:
            gt.table_html = gold["table_html"] or None
            gt.table_html_source = "human-reviewed table reference (gold slot)"
            gt.metadata["table_gold_reference"] = gold
        return gt

    @staticmethod
    def _apply_reviewed_reference_repairs(doc_path: Path, gt: GroundTruth) -> None:
        """Source-image-reviewed corrections; never rewrite historical sidecars.

        These are page-specific annotation repairs, not permissive scoring
        normalization. A website printed on another page must still be read.
        """
        if doc_path.stem in {f"invoice_{i:03d}" for i in range(6)}:
            GroundTruthLoader._repair_invoice_text(doc_path, gt)
        if doc_path.stem in {"sroie_000", "sroie_002", "sroie_003", "sroie_004", "sroie_005"}:
            GroundTruthLoader._repair_receipt_references(doc_path, gt)

        source_urls = {
            "scanned_000": "http://industrydocuments.library.ucsf.edu/tobacco/docs/klpb0135",
            "scanned_001": "https://www.industrydocuments.ucsf.edu/docs/hqcx0242",
            "scanned_002": "https://www.industrydocuments.ucsf.edu/docs/hlhj0239",
            "scanned_003": "https://www.industrydocuments.ucsf.edu/docs/kykb0006",
            "scanned_004": "https://www.industrydocuments.ucsf.edu/docs/fnpd0075",
            "scanned_005": "https://www.industrydocuments.ucsf.edu/docs/ksdd0025",
        }
        if doc_path.stem in source_urls:
            citation = "Source: " + source_urls[doc_path.stem]
            if gt.plain_text.count(citation) == 1:
                gt.plain_text = gt.plain_text.replace(citation, "").strip()
                gt.metadata["text_reference_repairs"] = {
                    "version": "printed-text-reference-v1 (2026-10-02)",
                    "removed_unprinted_source_citation": citation,
                }

        if doc_path.stem != "chart_003":
            return
        import hashlib
        expected_hash = "b5b334a63ed44de99dfc40b9c9354ef475d024a9bba7686e8446c4698a7e1e3e"
        if hashlib.sha256(gt.plain_text.encode()).hexdigest() != expected_hash:
            raise ValueError("chart_003 text reference changed; review its printed-text repair")
        original = gt.plain_text
        # Transcribed from the two charts' printed titles, ticks, categories
        # and legends. There are no printed segment counts or table grids.
        printed_charts = (
            "Figure 20: Global Workforce by Employment Level\n\n"
            "12,000 10,000 8,000 6,000 4,000 2,000 0\n"
            "2020 2019 2018 2017\n"
            "Executive & Senior Management\n"
            "Management Professional Professional Support\n"
            "Administration Operations\n\n"
            "Figure 21: Global Workforce by Age and Gender\n\n"
            "10,000 8,000 6,000 4,000 2,000 0\n"
            "F M 2020 F M 2019 F M 2018 F M 2017\n"
            "0–24 25–34 35–44 45–54 55–64 65+\n"
            "F=Female M=Male\n\n"
        )
        gt.plain_text = printed_charts + original[original.index("Our COVID-19 Response"):]
        if gt.markdown == original:
            gt.markdown = gt.plain_text
        gt.metadata["text_reference_repairs"] = {
            "version": "printed-text-reference-v1 (2026-10-02)",
            "original_sha256": expected_hash,
            "replaced": "inferred chart data tables with source-verified printed chart text",
        }
        # The old annotation includes approximate/incorrect bar heights as
        # exact answers (e.g. Operations=5,500, visibly near 6,500 in 2020).
        # Even the rounded gender series has doubtful boundary values. Keep
        # titles/axes/legends and the plainly largest category; exclude the
        # quantitative series until separately annotated with a suitable
        # chart-estimation tolerance. No guessed replacement counts or nulls.
        excluded = ["employmentLevelBreakdown", "ageAndGenderBreakdown", "workforceByGender"]
        if isinstance(gt.true_json, dict) and isinstance(gt.json_schema, dict):
            for key in excluded:
                gt.true_json.pop(key, None)
                gt.json_schema.get("properties", {}).pop(key, None)
            gt.json_schema["required"] = [
                key for key in gt.json_schema.get("required", []) if key not in excluded]
            gt.metadata["structured_reference_repairs"] = {
                "version": "chart-reference-v1 (2026-10-02)",
                "excluded_unverified_chart_series": excluded,
                "reason": "bar estimates are not verified exact OCR values",
            }

    @staticmethod
    def _repair_invoice_text(doc_path: Path, gt: GroundTruth) -> None:
        """Use the six page-reviewed transcriptions, preserving raw sidecars.

        The older plain-text annotations contain phantom punctuation/numbers,
        joined amounts, wrong row numbers and interleaved reading order.
        Existing Markdown transcriptions were rechecked against all six
        images; only two unreadable replacement-glyph spans need exclusion.
        """
        import hashlib
        import re
        from evaluation.metrics import _markdown_to_plain

        hashes = {
            "invoice_000": ("068eb101a1b35f1ebd072794573f91375bd3b679478c1aea6729c2f9be47f51e", "f69ea7a916b3bf3bff17b656a0e215a09e32ac87325b0b69f51551f3c5ea0d14"),
            "invoice_001": ("1ca9e74d5363b06e26eb3183b4f4500d8d7e164d7b5c4031b89c6e3fe8ff125a", "a4aaa62cdb29b089f9d016f0f683cf05ef3cd9a26d797de9bbda23e16500ee86"),
            "invoice_002": ("cbdb151334be49adbf6c05150e7c79b29c6e353f7d9f5e1dc832d49a17723737", "cc9ff97b8de63969eda734cb318780235c36b6b29ac3ccf1c6aee7e6d908864b"),
            "invoice_003": ("52ff243f5b12520e759044310746fea6b60a06d258ebff3f4e0bd35ffec6cd49", "41bbeb9f005cbe5a6d85beb76ee42a84ac8d8117051b42636ccad3636f6ce15d"),
            "invoice_004": ("153bf1c84039f38e3e5bd91a26d901b41323521b30889d6b7ba319eb234bb7d8", "e6b6d01c616c6a07c4be7d41913f3f26b1346148f64b23c3e33872084b1112e6"),
            "invoice_005": ("04630b8d1efd624d3c8f67cb3a26972a492efd2189fa7c3d04c8c1cbe93c5082", "7a6bdb4bfc24fe44ff2f8c4c8805155ee8e8204d34b7a7439e00e7ab65b8ebe5"),
        }
        original_hash, markdown_hash = hashes[doc_path.stem]
        if (hashlib.sha256(gt.plain_text.encode()).hexdigest() != original_hash or
                hashlib.sha256((gt.markdown or "").encode()).hexdigest() != markdown_hash):
            raise ValueError(f"{doc_path.stem} reference changed; review its printed-text repair")
        excluded = []
        corrected = []
        if doc_path.stem == "invoice_004":
            gt.markdown = gt.markdown.replace("Picturebook 00000000", "Picturebook")
            gt.table_html = gt.table_html.replace("Picturebook 00000000", "Picturebook")
            gt.true_json["items"][2]["item_desc"] = gt.true_json["items"][2]["item_desc"].removesuffix(" 00000000")
            excluded = ["items[2].item_desc"]
        elif doc_path.stem == "invoice_005":
            gt.markdown = gt.markdown.replace('PREORDER"00OO', "**PREORDER**")
            gt.table_html = gt.table_html.replace("PREORDER&quot;00OO", "**PREORDER**")
            gt.true_json["items"][0]["item_desc"] = gt.true_json["items"][0]["item_desc"].replace('PREORDER"00OO', "**PREORDER**")
            # The image prints a slash here, not the annotation's capital I.
            gt.true_json["items"][4]["item_desc"] = gt.true_json["items"][4]["item_desc"].replace('White "I TESTED', 'White " / TESTED')
            excluded = ["items[0].item_desc"]
            corrected = ["items[4].item_desc"]
        # Remove old annotation comments, including claims that guessed glyph
        # transcriptions are retained. The review is recorded as metadata.
        gt.markdown = re.sub(r"<!--.*?-->", "", gt.markdown, flags=re.S).strip()
        gt.plain_text = _markdown_to_plain(gt.markdown).strip()
        gt.metadata["text_reference_repairs"] = {
            "version": "invoice-printed-text-v1 (2026-10-02)",
            "original_sha256": original_hash,
            "reviewed_markdown_sha256": markdown_hash,
            "method": "source-image review of all six pages; render their verified transcription to plain text",
            "excluded_unreadable_spans": excluded,
        }
        if excluded or corrected:
            gt.metadata["structured_reference_repairs"] = {
                "version": "invoice-reference-v1 (2026-10-02)",
                "excluded_fields": excluded,
                "corrected_fields": corrected,
                "reason": "description has unreadable replacement glyphs; full-string equality is unscorable, readable prefix remains in text/table targets",
            }

    @staticmethod
    def _repair_receipt_references(doc_path: Path, gt: GroundTruth) -> None:
        """Repair source-reviewed line text; preserve every retained box.

        Five receipts omit readable address suffixes from both text and box
        labels, even though the boxes cover the full printed lines. Changes
        are annotation-specific, not matching tolerances or engine-derived GT.
        """
        import hashlib

        hashes = {
            "sroie_000": ("5fa0991b6cf06029849f4425da20f0d2f43b88ee79ca9e9ea9898347dfa0dd3f", "b435c6b9d591a788f046b5638ba33d66d6201eb27efc9b0b7c405a70ca48687f"),
            "sroie_002": ("3d46dfb1b59254d84be37dc9544d77f3b5343ec168315918e2da1cd441e84aa1", "6a0ec53db8da28b7be2fda908968285a26386f47228836ada723d65eee30842b"),
            "sroie_003": ("bef038d75449e0281dfadd97bb9ca49fd4e341d3e0b494f70fee0c86d9e90dd8", "a22cec356e56d282f81e5379ece36ea21f9415dfedb83a8fbd5ffc62fe21be64"),
            "sroie_004": ("3f33ed47a137f2a0f66ea44ec5b81e922f63f512734c84a40243470a4a6742ae", "074b9aa77adce47dcaf79cc000b7102037a9ada6fe1a408f8014dee15d009dc8"),
            "sroie_005": ("e9cb29c80f7c421298453c8a686d6fe5af0ebb9b5ed4663ce4ded47ba315d118", "eb5acad17a78ded46906835fe8e728f98643d7de2487a592e77f5a7cc921190b"),
        }
        text_hash, box_hash = hashes[doc_path.stem]
        if (hashlib.sha256(gt.plain_text.encode()).hexdigest() != text_hash or
                hashlib.sha256(json.dumps(gt.word_boxes, sort_keys=True).encode()).hexdigest() != box_hash):
            raise ValueError(f"{doc_path.stem} reference changed; review its receipt repair")
        replacements = {
            "sroie_000": [
                ("NO 2 & 4 BANDAR SERI ALAM 81750 MASAI", "NO 2 & 4, JALAN BAYU 4, BANDAR SERI ALAM, 81750 MASAI, JOHOR"),
            ],
            "sroie_002": [
                ("LOT 13 SIN LIANHAP SDN BHD LOT 13 KG BATU 30 44300 BTG KALI",
                 "LOT 13, JALAN SIN LIANHAP SDN BHD LOT 13, JALAN IPOH, KG BATU 30, ULU YAM LAMA 44300 BTG KALI, SELANGOR."),
                ("INVOLCE", "INVOICE"), ("INCLUSLVE", "INCLUSIVE"), ("AMONUT", "AMOUNT"),
            ],
            "sroie_003": [
                ("NO. 5-7 SEKYSEN 4 BATANG KALI", "NO. 5-7, JALAN MAHAGONI 7/1, SEKYSEN 4, BANDAR UTAMA, 44300 BATANG KALI, SELANGOR."),
                ("8.00 TOTAL QTY : TOTAL AMOUNT", "8.00 TOTAL AMOUNT"),
            ],
            "sroie_004": [("BATU 3 51200", "BATU 3, JALAN IPOH 51200")],
            "sroie_005": [("22A-1 SECTION 17 46400 PETALING JAYA", "22A-1, JALAN 17/54, SECTION 17, 46400 PETALING JAYA,")],
        }[doc_path.stem]
        for old, new in replacements:
            if gt.plain_text.count(old) != 1:
                raise ValueError(f"Reviewed receipt text missing or ambiguous: {old}")
            gt.plain_text = gt.plain_text.replace(old, new, 1)
        # Indexes refer to the preserved original sidecar, before exclusions.
        labels = {
            "sroie_000": {4: "NO 2 & 4, JALAN BAYU 4,", 5: "BANDAR SERI ALAM,", 6: "81750 MASAI, JOHOR"},
            "sroie_002": {3: "LOT 13, JALAN IPOH,", 4: "KG BATU 30, ULU YAM LAMA", 5: "44300 BTG KALI, SELANGOR.",
                          11: "INVOICE NO.:", 33: "TOTAL SALES INCLUSIVE OF GST:", 44: "AMOUNT"},
            "sroie_003": {2: "NO. 5-7, JALAN MAHAGONI 7/1,", 3: "SEKYSEN 4, BANDAR UTAMA, 44300", 4: "BATANG KALI, SELANGOR."},
            "sroie_004": {4: "BATU 3, JALAN IPOH"},
            "sroie_005": {1: "22A-1, JALAN 17/54,", 2: "SECTION 17,", 3: "46400 PETALING JAYA,"},
        }[doc_path.stem]
        changes = []
        for index, new in labels.items():
            word = gt.word_boxes[index]
            changes.append({"source_index": index, "old": word["text"], "new": new})
            word["text"] = new
        excluded = {}
        if doc_path.stem == "sroie_002":
            excluded[1] = "faded first address line has an unreadable suffix; readable prefix retained in text only"
        elif doc_path.stem == "sroie_003":
            if gt.word_boxes[20] != gt.word_boxes[15]:
                raise ValueError("Reviewed duplicate TOTAL QTY box changed")
            excluded[20] = "duplicate TOTAL QTY annotation: same text and box as source index 15, one printed occurrence"
        excluded_boxes = [{"source_index": i, **gt.word_boxes[i], "reason": reason}
                          for i, reason in excluded.items()]
        gt.word_boxes = [word for i, word in enumerate(gt.word_boxes) if i not in excluded]
        gt.metadata["text_reference_repairs"] = {
            "version": "receipt-reference-v1 (2026-10-02)", "original_sha256": text_hash,
            "method": "source-image review of specified address omissions, label typos and duplicate annotation; remaining transcription not certified",
            "replacements": [{"old": old, "new": new} for old, new in replacements],
            "excluded_unreadable_spans": (["sroie_002 first faded address suffix"] if doc_path.stem == "sroie_002" else []),
        }
        gt.metadata["geometry_reference_repairs"] = {
            "version": "receipt-reference-v1 (2026-10-02)", "original_boxes_sha256": box_hash,
            "text_changes": changes, "excluded_boxes": excluded_boxes,
            "retained_coordinates_unchanged": True,
        }
        if doc_path.stem == "sroie_000":
            old = "KINGS SAFETY SHOES KWD 805"
            if gt.true_json["items"][0]["description"] != old:
                raise ValueError("Reviewed receipt shoe description changed")
            gt.true_json["items"][0]["description"] = "KINGS SAFETY SHOES KWD B05"
            gt.metadata["structured_reference_repairs"] = {
                "version": "receipt-reference-v1 (2026-10-02)",
                "corrected_fields": ["items[0].description"],
                "reason": "source prints B05; structured reference used 805; text and table references already use B05",
            }
        elif doc_path.stem == "sroie_003":
            GroundTruthLoader._repair_receipt_item_rows(gt)

    @staticmethod
    def _repair_receipt_item_rows(gt: GroundTruth) -> None:
        """One purchased item spans two description lines on sroie_003.

        The image has one quantity/price/amount and Total Qty: 1. Its table
        reference already joins the description; the structured annotation
        incorrectly created a second item with three phantom blank fields.
        The request schema permits any array length and is not changed.
        """
        expected = [
            {"description": "20X30 BEG 1KG91X30)", "qty": None, "price": None, "amount": None},
            {"description": "20X30 1KG", "qty": "1", "price": "8.00", "amount": "8.00"},
        ]
        if gt.true_json["items"] != expected or gt.true_json["total_qty"] != "1":
            raise ValueError("Reviewed sroie_003 item annotation changed")
        gt.true_json["items"] = [{
            "description": "20X30 BEG 1KG91X30) 20X30 1KG",
            "qty": "1", "price": "8.00", "amount": "8.00",
        }]
        gt.metadata["structured_reference_repairs"] = {
            "version": "receipt-item-reference-v1 (2026-10-02)",
            "corrected_fields": ["items"], "original_items": expected,
            "reason": "one purchased item with a two-line description; remove duplicate item and three nonexistent blank fields",
        }

    def _attach_geometry(self, doc_path: Path, gt: GroundTruth) -> None:
        """Word boxes for the geometry leg, where a sidecar exists (17 docs).

        Boxes are normalised 0-1 against the shipped image's own dimensions;
        each sidecar records its source dataset, coordinate system and the
        verification that its words appear in the text reference. FUNSD's
        source boxes are LayoutLM-style 0-1000, not pixels — dividing by the
        image size corrupted every x-coordinate once, which is why the
        normalisation is stated per file rather than assumed.
        """
        sidecar = doc_path.parent / (doc_path.stem + "_geometry_gt.json")
        if not sidecar.exists():
            return
        try:
            data = json.loads(sidecar.read_text(encoding="utf-8"))
            words = data.get("words") or []
        except Exception:
            return
        if words:
            gt.word_boxes = words
            gt.word_boxes_granularity = data.get("granularity")

    def _infer_tier_type(self, document_path: Path) -> tuple[str, str]:
        parts = document_path.parts
        # Expect .../documents/{tier}/{doc_type}/filename
        try:
            doc_idx = parts.index("documents")
            tier = parts[doc_idx + 1]
            doc_type = parts[doc_idx + 2]
            return tier, doc_type
        except (ValueError, IndexError):
            return "unknown", "unknown"

    def _load_txt_gt(
        self, doc_path: Path, gt_path: Path, tier: str, doc_type: str
    ) -> GroundTruth:
        plain_text = gt_path.read_text(encoding="utf-8").strip()
        gt_source = _classify_gt(doc_path, doc_type)
        return GroundTruth(
            document_path=str(doc_path),
            tier=tier,
            doc_type=doc_type,
            plain_text=plain_text,
            gt_source=gt_source,
            dataset=(MANIFEST.get(doc_path.stem) or {}).get("dataset"),
        )

    def _load_json_gt(
        self, doc_path: Path, gt_path: Path, tier: str, doc_type: str
    ) -> GroundTruth:
        data = json.loads(gt_path.read_text(encoding="utf-8"))
        plain_text = data.get("plain_text", "")
        table_html = data.get("table_html")
        has_formulas = data.get("has_formulas", False)
        gt_source = _classify_gt(doc_path, doc_type)
        return GroundTruth(
            document_path=str(doc_path),
            tier=tier,
            doc_type=doc_type,
            plain_text=plain_text,
            table_html=table_html,
            table_html_source=data.get("table_html_source"),
            has_formulas=has_formulas,
            gt_source=gt_source,
            dataset=(MANIFEST.get(doc_path.stem) or {}).get("dataset"),
        )

    def _attach_markdown(self, doc_path: Path, gt: GroundTruth) -> None:
        from evaluation.markdown_catalogue import reviewed_items
        catalogue = reviewed_items(doc_path)
        if catalogue:
            gt.metadata['reviewed_markdown_catalogue'] = catalogue
        sidecar = doc_path.parent / (doc_path.stem + "_markdown_gt.md")
        if sidecar.exists():
            gt.markdown = sidecar.read_text(encoding="utf-8")
            gt.markdown_source = "sidecar"
            return
        if gt.dataset in MARKDOWN_NATIVE_DATASETS and gt.plain_text:
            # Not a copy of a different reference: for these datasets the
            # annotation was authored as markdown in the first place.
            gt.markdown = gt.plain_text
            gt.markdown_source = "gt_txt_is_markdown"

    def _attach_structured(self, doc_path: Path, gt: GroundTruth) -> None:
        sidecar = doc_path.parent / (doc_path.stem + "_structured_gt.json")
        if not sidecar.exists():
            return
        data = json.loads(sidecar.read_text(encoding="utf-8"))
        gt.json_schema = data.get("json_schema")
        gt.true_json = data.get("true_json")
        gt.field_provenance = data.get("field_provenance")
        gt.structured_note = data.get("note")
        if gt.doc_type == "financial_table" and isinstance(gt.true_json, dict):
            from evaluation.schema_contract import repair_spanned_financial_rows
            had_csv = "csv" in gt.true_json
            gt.true_json, repaired = repair_spanned_financial_rows(gt.true_json, gt.table_html or "")
            # The supplied schema never asked engines to return this derived CSV.
            gt.true_json.pop("csv", None)
            gt.metadata["structured_reference_repairs"] = {
                "version": "financial-reference-v1 (2026-10-02)",
                "spanning_headers_corrected": repaired,
                "unrequested_csv_removed": had_csv,
            }


def load_corpus(
    documents_root: Path | None = None, tiers: list[str] | None = None
) -> list[GroundTruth]:
    """Every document in the corpus, loaded through the loader.

    Used by the report's provenance table and by `--dry-run`, so the counts
    printed there are the counts scoring will see.
    """
    root = documents_root or DOCUMENTS_ROOT
    loader = GroundTruthLoader()
    out = []
    for tier_dir in sorted(p for p in root.iterdir() if p.is_dir()):
        if tiers and tier_dir.name not in tiers:
            continue
        for doc in sorted(tier_dir.rglob("*")):
            if doc.suffix.lower() not in (".png", ".jpg", ".jpeg", ".pdf"):
                continue
            if "_gt" in doc.stem:
                continue
            out.append(loader.load(doc))
    return out
